data class Episode(val id:String,val no:Int,val title:String,val sarga:String,val minutes:Int,val en:String,val te:String,val hi:String,val verified:Boolean)
data class Kanda(val name:String,val subtitle:String,val index:String)
private val kandas=listOf(Kanda("Bala Kanda","Origins and early life","01"),Kanda("Ayodhya Kanda","Ayodhya and exile","02"),Kanda("Aranya Kanda","Life in the forest","03"),Kanda("Kishkindha Kanda","Alliance in Kishkindha","04"),Kanda("Sundara Kanda","Hanuman's journey","05"),Kanda("Yuddha Kanda","The great war","06"),Kanda("Uttara Kanda","Later account","07"))
private val bala=listOf(
 Episode("BK01",1,"Valmiki's Question to Narada","Sarga 1",20,"Valmiki asks Narada whether there is a person who embodies an exceptional group of virtues. Narada identifies Rama of the Ikshvaku line and begins a concise account of his qualities and life. This short text is a prototype summary, not a substitute for the complete Sanskrit passage.","వాల్మీకి మహర్షి నారదుని ఉత్తమ గుణాలు కలిగిన పురుషుడు ఎవరో అడుగుతాడు. నారదుడు ఇక్ష్వాకు వంశానికి చెందిన రాముని పరిచయం చేసి ఆయన గుణాలు మరియు జీవితాన్ని సంక్షిప్తంగా వివరిస్తాడు. ఇది నమూనా సారాంశం మాత్రమే.","वाल्मीकि नारद से ऐसे श्रेष्ठ पुरुष के विषय में पूछते हैं जिसमें उत्तम गुण हों। नारद इक्ष्वाकु वंश के राम का परिचय देते हैं और उनके गुणों तथा जीवन का संक्षिप्त वर्णन आरम्भ करते हैं। यह केवल नमूना सारांश है।",true),
 Episode("BK02",2,"Narada's Account of Rama","Sarga 1",20,"Narada continues the compressed narration of Rama's story, describing his character and key events that the epic will later unfold in detail. This episode slot is ready for a verse-mapped 20-minute approved script.","నారదుడు రాముని గుణాలను మరియు తరువాత విస్తరించబోయే ముఖ్య సంఘటనలను సంక్షిప్తంగా చెబుతాడు. పూర్తి 20 నిమిషాల పాఠాన్ని సర్గలోని శ్లోకాలతో సరిపోల్చి ఆమోదించిన తరువాత చేర్చాలి.","नारद राम के गुणों और आगे विस्तार से आने वाली प्रमुख घटनाओं का संक्षिप्त वर्णन करते हैं। पूर्ण 20 मिनट की कथा श्लोक-स्तरीय समीक्षा के बाद जोड़ी जानी है।",false),
 Episode("BK03",3,"The Krauncha Birds","Sarga 2",20,"At the Tamasa river, Valmiki witnesses the killing of one of a pair of krauncha birds. His grief takes metrical form. The episode is foundational to the traditional account of the poem's composition.","తమసా నది వద్ద వాల్మీకి క్రౌంచ పక్షుల జంటలో ఒకటి వేటగాడి చేతిలో చనిపోవడాన్ని చూస్తాడు. ఆయన శోకం ఛందోబద్ధమైన రూపంలో వెలువడుతుంది.","तमसा नदी के निकट वाल्मीकि क्रौंच पक्षियों के जोड़े में से एक की मृत्यु देखते हैं। उनका शोक छन्दबद्ध रूप में प्रकट होता है।",true),
 Episode("BK04",4,"Brahma Appears to Valmiki","Sarga 2-3",20,"The composition story continues with Brahma's appearance and Valmiki's undertaking to narrate Rama's life. Exact verse boundaries and final narration remain a release-gate item.","బ్రహ్మ వాల్మీకికి ప్రత్యక్షమై రాముని కథను రచించడానికి ప్రేరేపించే సందర్భం కొనసాగుతుంది. తుది విడుదలకు ముందు ఖచ్చితమైన శ్లోక పరిధిని సమీక్షించాలి.","ब्रह्मा वाल्मीकि के समक्ष प्रकट होते हैं और रामकथा की रचना का प्रसंग आगे बढ़ता है। अंतिम प्रकाशन से पहले श्लोक सीमा की समीक्षा आवश्यक है।",false)
)
class MainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);setContent{Ramayanam()}}}
@Composable fun Ramayanam(){
 val ctx=LocalContext.current;val p=remember{ctx.getSharedPreferences("ramayanam",0)};var lang by remember{mutableStateOf(p.getString("lang","Telugu")!!)};var page by remember{mutableStateOf("home")};var current by remember{mutableStateOf<Episode?>(null)};var query by remember{mutableStateOf("")};var fav by remember{mutableStateOf(p.getStringSet("fav",emptySet())!!.toSet())};var dark by remember{mutableStateOf(p.getBoolean("dark",false))}
 val scheme=if(dark)darkColorScheme(primary=Color(0xFFFFB4A8),secondary=Color(0xFFE9C36A)) else lightColorScheme(primary=Color(0xFF7B291B),secondary=Color(0xFF9A6A05),background=Color(0xFFFFF8ED),surface=Color(0xFFFFFBF5))
 MaterialTheme(scheme){Scaffold(bottomBar={if(page!="player")NavigationBar{listOf("home" to Icons.Default.Home,"search" to Icons.Default.Search,"library" to Icons.Default.Favorite,"about" to Icons.Default.Info).forEach{(n,i)->NavigationBarItem(page==n,{page=n},{Icon(i,n)},{Text(n.replaceFirstChar{it.uppercase()})})}}}){pad->when(page){"player"->Player(pad,current!!,lang,{page="home"});"search"->Search(pad,query,{query=it},{current=it;page="player"});"library"->Library(pad,fav,{current=it;page="player"});"about"->About(pad,dark,{dark=!dark;p.edit().putBoolean("dark",dark).apply()});else->Home(pad,lang,{lang=it;p.edit().putString("lang",it).apply()},fav,{id->fav=if(id in fav)fav-id else fav+id;p.edit().putStringSet("fav",fav).apply()},{current=it;page="player"})}}}
}
@Composable fun Hero(){Card(colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.primary)){Column(Modifier.fillMaxWidth().padding(22.dp)){Text("RAMAYANAM",color=Color.White,style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);Text("Listen • Read • Reflect",color=Color.White);Spacer(Modifier.height(12.dp));Text("Valmiki Ramayana",color=Color(0xFFFFDFA0),style=MaterialTheme.typography.titleLarge)}}}
@Composable fun Home(pad:PaddingValues,lang:String,setLang:(String)->Unit,fav:Set<String>,toggle:(String)->Unit,open:(Episode)->Unit){LazyColumn(Modifier.padding(pad).padding(16.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{Hero()};item{Text("Language",fontWeight=FontWeight.Bold);SingleChoiceSegmentedButtonRow{listOf("Telugu","Hindi","English").forEachIndexed{i,l->SegmentedButton(lang==l,{setLang(l)},SegmentedButtonDefaults.itemShape(i,3)){Text(l)}}}};item{Text("Explore the Ramayana",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold)};items(kandas){k->Card{Row(Modifier.fillMaxWidth().padding(16.dp),verticalAlignment=Alignment.CenterVertically){Text(k.index,style=MaterialTheme.typography.headlineSmall,color=MaterialTheme.colorScheme.secondary);Spacer(Modifier.width(16.dp));Column{Text(k.name,fontWeight=FontWeight.Bold);Text(k.subtitle,style=MaterialTheme.typography.bodySmall)}}}};item{Text("Bala Kanda • first production set",style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold)};items(bala){e->EpisodeCard(e,e.id in fav,toggle,open)}}}
@Composable fun EpisodeCard(e:Episode,isFav:Boolean,toggle:(String)->Unit,open:(Episode)->Unit){Card(onClick={open(e)}){Column(Modifier.padding(16.dp)){Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("Episode ${e.no}",color=MaterialTheme.colorScheme.primary);Text(e.title,style=MaterialTheme.typography.titleMedium,fontWeight=FontWeight.Bold);Text("${e.sarga} • target ${e.minutes} min")};IconButton({toggle(e.id)}){Icon(if(isFav)Icons.Default.Favorite else Icons.Default.FavoriteBorder,"Favourite")}};Text(if(e.verified)"Source-mapped prototype" else "Editorial review pending",style=MaterialTheme.typography.labelMedium,color=MaterialTheme.colorScheme.secondary)}}}
@Composable fun Player(pad:PaddingValues,e:Episode,lang:String,back:()->Unit){
 val ctx=LocalContext.current
 var media by remember { mutableStateOf<MediaPlayer?>(null) }
 var playing by remember { mutableStateOf(false) }
 val audioName = remember(e.id,lang){ "${e.id.lowercase()}_${when(lang){"Telugu"->"te";"Hindi"->"hi";else->"en"}}" }
 val resId = remember(audioName){ ctx.resources.getIdentifier(audioName,"raw",ctx.packageName) }
 DisposableEffect(Unit){ onDispose { media?.release() } }
 LazyColumn(Modifier.padding(pad).padding(18.dp),verticalArrangement=Arrangement.spacedBy(16.dp)){
  item{IconButton({media?.release();back()}){Icon(Icons.Default.ArrowBack,"Back")};Text("Episode ${e.no} • ${e.sarga}",color=MaterialTheme.colorScheme.primary);Text(e.title,style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);Text("$lang • embedded narration • target ${e.minutes} min")}
  item{Card{Column(Modifier.padding(18.dp)){Text("Premium narration",fontWeight=FontWeight.Bold);Text(if(resId!=0)"Audio is stored inside this app and plays without internet." else "Narration file is not embedded yet. Add $audioName.mp3 to app/src/main/res/raw/." )}}}
  item{Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceEvenly){FilledIconButton(onClick={if(resId!=0){if(media==null){media=MediaPlayer.create(ctx,resId);media?.setOnCompletionListener{playing=false}};media?.start();playing=true}},enabled=resId!=0){Icon(Icons.Default.PlayArrow,"Play")};OutlinedIconButton(onClick={media?.pause();playing=false},enabled=resId!=0){Icon(Icons.Default.Pause,"Pause")};OutlinedIconButton(onClick={media?.seekTo(0);media?.pause();playing=false},enabled=resId!=0){Icon(Icons.Default.Stop,"Stop")}}}
  item{Text(if(playing)"Now playing" else "Ready",color=MaterialTheme.colorScheme.primary)}
  item{Card{Column(Modifier.padding(16.dp)){Text("Source transparency",fontWeight=FontWeight.Bold);Text("Bala Kanda • ${e.sarga}");Text(if(e.verified)"Prototype mapped to this Sarga. Final narration audio must use a rights-cleared voice performance and approved script." else "Episode remains blocked until exact source mapping, script approval and licensed/original narration audio are completed.")}}}
 }
}
@Composable fun Search(pad:PaddingValues,q:String,setQ:(String)->Unit,open:(Episode)->Unit){LazyColumn(Modifier.padding(pad).padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("Search",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);OutlinedTextField(q,setQ,Modifier.fillMaxWidth(),label={Text("Episode, Sarga, character...")},leadingIcon={Icon(Icons.Default.Search,null)})};items(bala.filter{q.isBlank()||it.title.contains(q,true)||it.sarga.contains(q,true)}){EpisodeCard(it,false,{},open)}}}
@Composable fun Library(pad:PaddingValues,fav:Set<String>,open:(Episode)->Unit){val list=bala.filter{it.id in fav};LazyColumn(Modifier.padding(pad).padding(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Text("My Library",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold)};if(list.isEmpty())item{Text("Save episodes with the heart icon and they will appear here.")};items(list){EpisodeCard(it,true,{},open)}}}
@Composable fun About(pad:PaddingValues,dark:Boolean,toggle:()->Unit){LazyColumn(Modifier.padding(pad).padding(16.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{Text("About Ramayanam",style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold);Text("Built as an offline-first multilingual listening and reading experience. No account, cloud service or network access is required for the prototype.")};item{Card{Column(Modifier.padding(16.dp)){Text("Authenticity standard",fontWeight=FontWeight.Bold);Text("Every production episode should retain exact Kanda/Sarga/verse provenance, original translation records and independent scholarly review before release.")}}};item{Row(verticalAlignment=Alignment.CenterVertically){Text("Dark theme",Modifier.weight(1f));Switch(dark,toggle)}}}}
